function solve(n, t) {
    const memo = new Map();
    return dp(1, 0, 0, 0, 0, n, t, memo);
}

function dp(x, prevY, humps, valleys, lastDir, n, t, memo) {
    if (x === n) {
        return (humps === t && valleys === t - 1) ? 1 : 0;
    }
    const key = `${x},${prevY},${humps},${valleys},${lastDir}`;
    if (memo.has(key)) return memo.get(key);

    let total = 0;
    for (let y = 1; y <= 4; y++) {
        if (y === prevY) continue;
        let newHumps = humps;
        let newValleys = valleys;
        let newDir = y > prevY ? 1 : -1;

        if (x >= 2) {
            if (lastDir === 1 && newDir === -1) newHumps++;
            else if (lastDir === -1 && newDir === 1) newValleys++;
        }

        if (newHumps > t || newValleys > t - 1) continue;

        total += dp(x + 1, y, newHumps, newValleys, newDir, n, t, memo);
    }

    memo.set(key, total);
